mapper.update:
WITH due AS (
 SELECT public_consent_session_id FROM seal.public_consent_session
 WHERE session_status='ACTIVE' AND expires_at<=#{now}
 ORDER BY expires_at,public_consent_session_id LIMIT #{limit} FOR UPDATE SKIP LOCKED
)
UPDATE seal.public_consent_session s SET session_status='EXPIRED',flow_hmac=NULL,flow_destroyed_at=#{now} FROM due WHERE s.public_consent_session_id=due.public_consent_session_id
